def ft_statistics(*args, **kwargs):
    """Print the requested statistics for the given numbers."""
    for stat in kwargs.values():
        try:
            if not args:
                raise ValueError('no data')
            ordered = sorted(args)
            n = len(ordered)
            if stat == 'mean':
                print('mean :', sum(args) / n)
            elif stat == 'median':
                mid = n // 2
                if n % 2 == 0:
                    print('median :', (ordered[mid - 1] + ordered[mid]) / 2)
                else:
                    print('median :', ordered[mid])
            elif stat == 'quartile':
                q1 = ordered[n // 4]
                q3 = ordered[(3 * n) // 4]
                print('quartile :', [float(q1), float(q3)])
            elif stat == 'std':
                mean = sum(args) / n
                variance = sum((x - mean) ** 2 for x in args) / n
                print('std :', variance ** 0.5)
            elif stat == 'var':
                mean = sum(args) / n
                variance = sum((x - mean) ** 2 for x in args) / n
                print('var :', variance)
            else:
                raise ValueError('unknown statistic')
        except (ValueError, ZeroDivisionError):
            print('ERROR')
